def list_():
    """
    List the RAID devices.

    CLI Example:

    .. code-block:: bash

        salt '*' raid.list
    """
    ret = {}
    for line in __salt__["raid.list_"]().split("\n"):
        if line:
            try:
                dev, level, raid_name = line.split()
            except ValueError:
                continue
            ret[dev] = {"level": level, "raid_name": raid_name}
    return ret

